    if reached_destination:
        return True

    if invalid_position:
        return False

    mark_visited(row, col)

    for each direction:
        if solve(next_row, next_col):
            return True

    unmark_position(row, col)

    return False

maze = [
    [1, 0, 0, 0],
    [1, 1, 0, 1],
    [0, 1, 0, 0],
    [1, 1, 1, 1]
]

n = 4
visited = [[False for _ in range(n)] for _ in range(n)]

def solve(row, col):
    if row == n - 1 and col == n - 1:
        return True

    if row < 0 or col < 0 or row >= n or col >= n:
        return False

    if maze[row][col] == 0 or visited[row][col]:
        return False

    visited[row][col] = True

    if solve(row + 1, col):
        return True

    if solve(row, col + 1):
        return True

    if solve(row - 1, col):
        return True

    if solve(row, col - 1):
        return True

    visited[row][col] = False

    return False

print(solve(0, 0))
